CREATE DATABASE IF NOT EXISTS incognitotech CHARACTER SET utf8mb4;
USE incognitotech;
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(40) UNIQUE NOT NULL,estado BOOL DEFAULT TRUE);
CREATE TABLE permisos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60) UNIQUE NOT NULL);
CREATE TABLE roles_permisos(rol_id INT,permiso_id INT,PRIMARY KEY(rol_id,permiso_id),FOREIGN KEY(rol_id) REFERENCES roles(id),FOREIGN KEY(permiso_id) REFERENCES permisos(id));
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(40),apellido VARCHAR(40),tipo_documento VARCHAR(10),numero_documento VARCHAR(12) UNIQUE,direccion VARCHAR(120),telefono VARCHAR(10),email VARCHAR(120) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,rol_id INT NOT NULL,estado BOOL DEFAULT TRUE,FOREIGN KEY(rol_id) REFERENCES roles(id));
